function admin_hidden(string $action,string $section,int $id=0): void {echo token().'<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="section" value="'.e($section).'"><input type="hidden" name="id" value="'.$id.'">';}
function afield(string $name,string $label,$value='',string $type='text',bool $required=true): void {global $old;$value=$old[$name]??$value;echo '<label>'.e($label);if($type==='textarea')echo '<textarea name="'.e($name).'" '.($required?'required':'').'>'.e($value).'</textarea>';else echo '<input name="'.e($name).'" type="'.e($type).'" '.($type==='file'?'accept="image/jpeg,image/png,image/webp"':'value="'.e($value).'"').' '.($required?'required':'').($type==='number'?' min="0" step="1"':'').($type==='password'?' autocomplete="new-password"':'').'>';echo '</label>';}
function aselect(string $name,string $label,array $options,$value=''): void {global $old;$value=$old[$name]??$value;echo '<label>'.e($label).'<select name="'.e($name).'" required>';foreach($options as $key=>$text)echo '<option value="'.e($key).'" '.((string)$value===(string)$key?'selected':'').'>'.e($text).'</option>';echo '</select></label>';}
function acheck(string $name,string $label,bool $checked): void {echo '<label class="checkbox"><input name="'.e($name).'" type="checkbox" '.($checked?'checked':'').'>'.e($label).'</label>';}
function delete_form(string $action,string $section,int $id,string $label='Delete'): void {?><form method="post" data-confirm="Delete this record? Records used elsewhere may be protected."><?php admin_hidden($action,$section,$id);?><button class="text-button danger"><?=e($label)?></button></form><?php }
